const assert = require('assert');

// Mock data to simulate the audit result with warnings
const auditResult = {
  title: 'Properly size images',
  description: 'Images should be properly sized',
  scoreDisplayMode: 'informative',
  warnings: [
    'Invalid image size information http://localhost/dobetterweb/480-318.jpg',
    'Unable to decode /dobetterweb/someotherjpg.jpg',
  ],
  score: 1,
};

// Function to render audit with warnings
function renderAuditWithWarnings(audit) {
  const auditDOM = document.createElement('div');
  auditDOM.classList.add('lh-audit');

  const title = document.createElement('div');
  title.classList.add('lh-audit__title');
  title.textContent = audit.title;
  auditDOM.appendChild(title);

  const description = document.createElement('div');
  description.classList.add('lh-audit__description');
  description.textContent = audit.description;
  auditDOM.appendChild(description);

  if (audit.warnings && audit.warnings.length > 0) {
    const warningEl = document.createElement('div');
    warningEl.classList.add('lh-warnings');
    warningEl.textContent = 'Warnings: ' + audit.warnings.join(', ');
    auditDOM.appendChild(warningEl);
  }

  return auditDOM;
}

// Test rendering
const auditDOM = renderAuditWithWarnings(auditResult);
assert.ok(auditDOM.querySelector('.lh-warnings'), 'Warnings should be rendered');
console.log(auditDOM.outerHTML);
